  if(action.equals("export-raw-part")){Object index=a.opt("index");String manifestSHA=a.getString("manifestSHA256"),rawStream=a.getString("stream");if(!Arrays.asList("bundle","native-closed-files").contains(rawStream))throw new IOException("RAW_STREAM_TYPED_SCOPE");if(!(index instanceof Number)||((Number)index).doubleValue()!=((Number)index).intValue()||((Number)index).intValue()<0||((Number)index).intValue()>5||!manifestSHA.matches("[a-f0-9]{64}"))throw new IOException("RAW_PART_TYPED_SCOPE");int part=((Number)index).intValue();HttpURLConnection c=(HttpURLConnection)new URL(ORIGIN+"/api/raw-part?index="+part+"&stream="+rawStream+"&manifestSHA256="+manifestSHA).openConnection();try{c.setInstanceFollowRedirects(false);c.setConnectTimeout(3000);c.setReadTimeout(10000);if(c.getResponseCode()!=200||!"aeris-betasim-raw-part".equals(c.getHeaderField("X-Aeris-Format"))||!Integer.toString(part).equals(c.getHeaderField("X-Aeris-Raw-Index"))||!manifestSHA.equals(c.getHeaderField("X-Aeris-Raw-Manifest"))||!rawStream.equals(c.getHeaderField("X-Aeris-Raw-Stream")))throw new IOException("RAW_PART_SOURCE_CONTEXT");String expected=c.getHeaderField("X-Aeris-Artifact-SHA256");long declared=c.getContentLengthLong();if(expected==null||!expected.matches("[a-f0-9]{64}")||declared<=0||declared>28L*1024*1024)throw new IOException("RAW_PART_HEADER_BOUND");try(InputStream in=c.getInputStream()){exportBytes=WorkspaceStore.read(in,32*1024*1024);}if(exportBytes.length!=declared||!WorkspaceStore.sha(exportBytes).equals(expected))throw new IOException("RAW_PART_ORIGINAL_SHA");exportSha=expected;}finally{c.disconnect();}}
