 private void reply(JSONObject q,JSONObject result,Exception error){deliver(q,result,error,true);}
 private void deliver(JSONObject q,JSONObject result,Exception error,boolean release){runOnUiThread(()->{if(release&&q!=null)gate.finish(q.optString("session")+":"+q.optString("id"));if(q==null||web==null||destroyed||!origin(web.getUrl()))return;try{JSONObject r=obj("version",1,"id",q.optString("id"),"instance",q.optString("instance"),"session",q.optString("session"),"action",q.optString("action"),"ok",error==null);if(error==null)r.put("result",result);else r.put("error",error.getMessage());web.evaluateJavascript("window.nativeWB02Reply&&window.nativeWB02Reply(JSON.parse("+JSONObject.quote(r.toString())+"))",null);}catch(Exception ignored){}});}
